/* Floating bottom-tab navigation: the fleet's canonical primary-nav component.
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * only the markup (which tabs exist) and the options passed at the call site
 * vary. Pairs with nav-tabs.css (the visual contract) and nav-tabs.html (the
 * markup skeleton). This file owns behaviour only; colour and spacing come
 * from the design tokens nav-tabs.css reads.
 *
 * Markup contract (see nav-tabs.html):
 *   <nav class="tabs" role="tablist" data-active-tab="…">
 *     <button class="tab" data-tab="NAME" role="tab"
 *             aria-controls="PANE_ID" aria-selected="…"> … </button> …
 *   </nav>
 *   <main class="app">
 *     <section id="PANE_ID" class="pane" role="tabpanel" aria-labelledby="…"> … </section>
 *   </main>
 *
 * Each .tab carries data-tab (its name) and aria-controls (the id of the pane
 * it shows); a tab may have no pane, and then only its button state changes.
 * The nav is a direct <body> child beside the .app content wrapper: an
 * installed iOS app can anchor a fixed descendant of a scroller to the
 * scrolled content. The tabs are discovered from the DOM, so adding or
 * removing one is a markup-only change. The modal-hide rule (no bar over an
 * open <dialog>) lives in nav-tabs.css.
 */

// Arrow key to tab-row direction. Up and Down also move, so the wide layout's
// vertical rail answers the keys its tabs are stacked along.
const ARROW_STEP = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };

// How far a finger may wander before a press becomes a slide; less is a tap.
const SLIDE_SLOP_PX = 8;
// iOS may still send a click after a short slide; one inside this window is dropped.
const SLIDE_CLICK_MS = 300;

/**
 * Wire up a .tabs nav: restore the last-active tab, switch panes on a tap or
 * on a press-and-slide across the phone pill, move between tabs with the arrow
 * keys, Home and End, and keep ARIA and the roving tabindex in sync.
 *
 * @param {object} [opts]
 * @param {string} [opts.navSelector='.tabs']   selector for the <nav> element.
 * @param {string|null} [opts.storageKey=null]  localStorage key for the active
 *   tab; omit / pass null to disable persistence.
 * @param {(tab: string) => void} [opts.onChange]  called after every switch
 *   (including the initial restore), with the active tab name.
 * @param {string|null} [opts.defaultTab=null]  tab to select when nothing is
 *   stored; defaults to the first tab in DOM order.
 * @returns {{
 *   setTab: (tab: string|null) => void,
 *   getTab: () => string|null,
 *   setBadge: (tab: string, count: number|null|undefined, noun?: string, tone?: string) => void,
 * }} setBadge shows a count badge on the tab named by data-tab: 1–9 render the
 *   digit, 10 and up render "9+", and 0 / null / undefined / a non-number remove
 *   it. The optional `noun` is what the count counts ("waiting"), spoken as part
 *   of the tab's accessible name: setBadge('board', 2, 'waiting') → "Board, 2
 *   waiting". The optional `tone` is 'attention' (the default) or 'danger', set
 *   as `data-tone` on the badge; any other value renders as attention. An unknown
 *   tab is ignored, so a poll loop can call it freely.
 *
 *   setTab(null) is "no tab active", for a screen that is not a tab (Settings,
 *   an archive): no tab carries the accent, aria-selected or the capsule, and
 *   getTab() returns null until the next real selection. It changes nothing
 *   else: the panes, the stored tab, the scroll and onChange are left to the
 *   app that opened the screen. Any other unknown name selects the fallback.
 */
export function initNavTabs({ navSelector = '.tabs', storageKey = null, onChange = () => {}, defaultTab = null } = {}) {
  const nav = document.querySelector(navSelector);
  if (!nav) throw new Error(`initNavTabs: no element matches "${navSelector}"`);
  const buttons = [...nav.querySelectorAll('.tab[data-tab]')];
  if (!buttons.length) throw new Error('initNavTabs: nav has no .tab[data-tab] buttons');

  const names = buttons.map((button) => button.dataset.tab);
  const fallback = names.includes(defaultTab) ? defaultTab : names[0];
  const capsule = createCapsule(buttons);
  let current = fallback;

  function clearTab() {
    current = null;
    // The bar stays reachable with Tab: its first laid-out tab holds the stop.
    const stop = capsule.cells()[0] || buttons[0];
    buttons.forEach((button) => {
      button.setAttribute('aria-selected', 'false');
      button.tabIndex = button === stop ? 0 : -1;
    });
    delete nav.dataset.activeTab;
    capsule.show(null);
  }

  function setTab(tab) {
    if (tab === null) return clearTab();
    current = names.includes(tab) ? tab : fallback;
    buttons.forEach((button) => {
      const on = button.dataset.tab === current;
      button.setAttribute('aria-selected', String(on));
      button.tabIndex = on ? 0 : -1;
      const pane = document.getElementById(button.getAttribute('aria-controls') || '');
      if (pane) pane.hidden = !on;
    });
    nav.dataset.activeTab = current;
    capsule.show(current);
    // Each pane opens at its top; the document is the only scroller.
    window.scrollTo(0, 0);
    if (storageKey) {
      try { localStorage.setItem(storageKey, current); } catch (_) { /* private mode */ }
    }
    onChange(current);
  }

  function setBadge(tab, count, noun, tone) {
    const button = buttons[names.indexOf(tab)];
    if (button) paintBadge(button, count, noun, tone);
  }

  const slide = watchSlide(nav, capsule, () => current, setTab);
  buttons.forEach((button) => {
    button.addEventListener('click', (event) => {
      if (!slide.strayClick(event)) setTab(button.dataset.tab);
    });
  });

  watchKeys(nav, capsule, setTab);

  let saved = null;
  if (storageKey) {
    try { saved = localStorage.getItem(storageKey); } catch (_) { /* private mode */ }
  }
  setTab(names.includes(saved) ? saved : fallback);
  // Mounted with its place already set, so it is born there and never slides in.
  nav.prepend(capsule.pill);
  // The cells move with no tap: a rotation or a width crossing, an app showing
  // or hiding a tab once its data arrives (the grid re-divides), the bar's
  // width settling after the standalone viewport expands. Follow without the
  // spring.
  const observer = new ResizeObserver(() => { if (!slide.active()) capsule.show(current, undefined, true); });
  buttons.forEach((button) => observer.observe(button));

  if (window.matchMedia('(display-mode: standalone)').matches) {
    mountTopEdge(nav);
    expandStandaloneViewport();
  }
  gateTopFade();

  return { setTab, getTab: () => current, setBadge };
}

// What the eye sees, as opposed to which tab is open: the accent on one tab
// and the capsule behind it. The capsule is inserted by the script, not the
// markup, so every app's nav HTML stays as it is; CSS shows it only in the
// phone pill.
function createCapsule(buttons) {
  const pill = document.createElement('span');
  pill.className = 'tab-pill';
  pill.setAttribute('aria-hidden', 'true');

  // The tabs laid out right now: an app may hide one until its data arrives.
  const cells = () => buttons.filter((button) => button.offsetWidth);

  // Park the capsule `x` px from the bar's edge, `w` wide. `jump` skips the
  // spring, for cells that moved under a resting capsule. Unchanged values
  // write nothing: iOS resizes the window on every keyboard open and close
  // without moving the cells, and a no-op write would still restyle and
  // repaint the glass bar.
  function place(x, w, jump) {
    const left = x + 'px';
    const width = w + 'px';
    if (pill.style.getPropertyValue('--pill-x') === left && pill.style.getPropertyValue('--pill-w') === width) return;
    if (jump) pill.style.transition = 'none';
    pill.style.setProperty('--pill-x', left);
    pill.style.setProperty('--pill-w', width);
    if (jump) {
      void pill.offsetWidth;
      pill.style.transition = '';
    }
  }

  // The accent on `tab` and the capsule under it, or at the fractional cell
  // index `at` while a finger drags it. At rest the capsule takes the tab's
  // own offsetLeft and offsetWidth, whole pixels. No tab and no finger hides
  // the capsule; it keeps its size, so the slide still finds the phone pill.
  function show(tab, at, jump) {
    buttons.forEach((button) => button.classList.toggle('active', button.dataset.tab === tab));
    const wasOff = pill.classList.contains('off');
    const off = tab === null && at === undefined;
    pill.classList.toggle('off', off);
    if (off) return;
    // Back from no tab, the capsule appears in place instead of springing.
    jump = jump || wasOff;
    const row = cells();
    if (!row.length) return;
    const i = at ?? Math.max(0, row.findIndex((button) => button.dataset.tab === tab));
    const from = row[Math.floor(i)];
    const to = row[Math.ceil(i)];
    const part = i - Math.floor(i);
    place(
      from.offsetLeft + (to.offsetLeft - from.offsetLeft) * part,
      from.offsetWidth + (to.offsetWidth - from.offsetWidth) * part,
      jump,
    );
  }

  return { pill, cells, show };
}

// WAI-ARIA tabs, automatic activation: an arrow moves focus to the next tab
// laid out (wrapping at the ends) and opens it; Home and End jump to the
// first and last. Tab itself reaches only the open tab (roving tabindex).
function watchKeys(nav, capsule, setTab) {
  nav.addEventListener('keydown', (event) => {
    const step = ARROW_STEP[event.key];
    const edge = event.key === 'Home' ? 0 : event.key === 'End' ? -1 : null;
    const from = event.target.closest?.('.tab[data-tab]');
    if ((step === undefined && edge === null) || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey || !from) return;
    const row = capsule.cells();
    const at = row.indexOf(from);
    if (at < 0) return;
    const to = edge === null ? row[(at + step + row.length) % row.length] : row.at(edge);
    event.preventDefault();
    setTab(to.dataset.tab);
    to.focus({ preventScroll: true });
  });
}

// Press-and-slide: past the slop the capsule follows the finger, the tab
// under it takes the accent, and lifting chooses that tab. Only in the phone
// pill, the one layout that shows the capsule. Returns what the rest of the
// nav asks of it: whether a finger is down on the bar, and whether a click is
// the stray one a phone sends after a slide.
function watchSlide(nav, capsule, getTab, setTab) {
  let slide = null;
  let slidAt = -Infinity;
  nav.addEventListener('pointerdown', (event) => {
    if (event.isPrimary && capsule.pill.offsetWidth) slide = { id: event.pointerId, x: event.clientX };
  });
  nav.addEventListener('pointermove', (event) => {
    if (!slide || event.pointerId !== slide.id) return;
    if (!slide.cells) {
      if (Math.abs(event.clientX - slide.x) < SLIDE_SLOP_PX) return;
      slide.cells = capsule.cells();
      const first = slide.cells[0].getBoundingClientRect();
      slide.origin = first.left + first.width / 2;
      slide.step = (slide.cells.at(-1).getBoundingClientRect().left - first.left) / (slide.cells.length - 1) || 1;
      nav.classList.add('sliding');
      nav.setPointerCapture(slide.id);
    }
    const at = Math.min(slide.cells.length - 1, Math.max(0, (event.clientX - slide.origin) / slide.step));
    slide.tab = slide.cells[Math.round(at)].dataset.tab;
    capsule.show(slide.tab, at);
  });
  function end(event) {
    if (!slide || event.pointerId !== slide.id) return;
    const { cells: slid, tab } = slide;
    slide = null;
    if (!slid) return;
    nav.classList.remove('sliding');
    slidAt = event.timeStamp;
    if (event.type === 'pointerup' && tab !== getTab()) setTab(tab);
    else capsule.show(getTab());
  }
  nav.addEventListener('pointerup', end);
  nav.addEventListener('pointercancel', end);
  return {
    active: () => slide !== null,
    strayClick: (event) => event.timeStamp - slidAt <= SLIDE_CLICK_MS,
  };
}

// iOS blurs an installed web app's top edge unless a real fixed element with a
// painted background sits there; a pseudo-element does not count. The strip
// (styled in nav-tabs.css) is inserted by the script, like the capsule, so
// every app's markup stays as it is: a direct <body> child just before the
// nav, never inside a scroller. Once, however often the nav is initialised.
function mountTopEdge(nav) {
  if (nav.parentElement.querySelector(':scope > .nav-top-edge')) return;
  const edge = document.createElement('div');
  edge.className = 'nav-top-edge';
  edge.setAttribute('aria-hidden', 'true');
  nav.before(edge);
}

// An installed iOS app opens with its viewport 59px short of the screen and,
// on a cold launch, grows it 1px at a time over ~3s, painting nothing below
// the moving edge, so the bar is revealed slowly. A 1px programmatic scroll
// asks iOS for the full-height viewport at once; the page goes straight back
// to the top. Once, at startup, and only when the page has not been scrolled.
function expandStandaloneViewport() {
  if (window.scrollY !== 0) return;
  window.scrollTo(0, 1);
  requestAnimationFrame(() => { if (window.scrollY === 1) window.scrollTo(0, 0); });
}

// The top glass (body::after in a browser tab, the .nav-top-edge strip in the
// installed app) follows the scroll position and nothing else: it does not
// exist at scroll-top, is generated on the first scrolled pixel and reaches
// full opacity over the first --nav-fade-band of scroll. A resize or a return
// to the foreground writes nothing to it or to the bar: the installed app's
// top-edge blur is a system effect the strip turns off, not a stale texture
// a repaint would clear (README, "Top-edge blur in the installed app").
let topGlassBand = 16;

function syncTopGlass() {
  const root = document.documentElement;
  const reveal = Math.min(1, Math.max(0, window.scrollY / topGlassBand));
  root.style.setProperty('--nav-fade-on', String(reveal));
  root.toggleAttribute('data-nav-top-glass', reveal > 0);
}

function gateTopFade() {
  const root = document.documentElement;
  topGlassBand = parseFloat(getComputedStyle(root).getPropertyValue('--nav-fade-band')) || 16;
  window.addEventListener('scroll', syncTopGlass, { passive: true });
  syncTopGlass();
}

// The count badge. Nothing here touches the DOM until an app calls setBadge.
// The first badge wraps the icon in .tab-icon-wrap, the box the badge is
// positioned against; the last one unwraps it, so a nav that never shows a
// badge keeps its markup. The digit is decoration (aria-hidden): the count is
// spoken once, by the zero-size text inside the label ("Board, 2 waiting").
function paintBadge(button, count, noun, tone) {
  const n = Math.floor(Number(count));
  const icon = button.querySelector('.tab-icon');
  let badge = button.querySelector('.tab-badge');
  let spoken = button.querySelector('.tab-badge-sr');
  if (!(n > 0)) {
    if (!badge) return;
    if (badge.parentElement !== button) badge.parentElement.replaceWith(icon);
    badge.remove();
    spoken.remove();
    return;
  }
  if (!badge) {
    badge = document.createElement('span');
    badge.className = 'tab-badge';
    badge.setAttribute('aria-hidden', 'true');
    spoken = document.createElement('span');
    spoken.className = 'tab-badge-sr';
    if (icon) {
      const wrap = document.createElement('span');
      wrap.className = 'tab-icon-wrap';
      icon.replaceWith(wrap);
      wrap.append(icon, badge);
    } else {
      button.append(badge);
    }
    (button.querySelector('.tab-label') || button).append(spoken);
  }
  badge.textContent = n > 9 ? '9+' : String(n);
  // Set on every call, so a count that escalates to danger (and settles back)
  // repaints the existing badge without removing it first.
  badge.dataset.tone = tone === 'danger' ? 'danger' : 'attention';
  spoken.textContent = ', ' + n + (noun ? ' ' + noun : '');
}
